-- ============================================================
-- DUNG MOD SKIN SYSTEM Ã¢â‚¬â€ standalone extract
-- No menu UI. All features on by default.
-- ============================================================

-- ---- required stubs (missing from game env) ----------------

-- Language (EN by default)
if not _G.LexusLang then _G.LexusLang = "EN" end

-- Translation passthrough (no real i18n needed)
local function T(en, other) return (_G.LexusLang == "EN") and en or (other or en) end

-- Notification (silent stub Ã¢â‚¬â€ replace with your notify impl if desired)
local function notify(msg) pcall(function() print("[SKIN] " .. tostring(msg)) end) end

-- Debug log Ã¢â‚¬â€ dual write: io.open path + engine Client.SaveStringToFile.
-- Buffered so SaveStringToFile (overwrite API) keeps full history.
local _SKIN_LOG = "/storage/emulated/0/Android/data/com.pubg.imobile/files/skin_debug.txt"
local _SKIN_BUF = {}
local function _skinFlush()
    local txt = table.concat(_SKIN_BUF, "\n")
    pcall(function()
        if Client and type(Client.SaveStringToFile) == "function" then
            Client.SaveStringToFile(txt, "SaveGames/skin_debug.txt")
        end
    end)
    pcall(function()
        if io and io.open then
            local f = io.open(_SKIN_LOG, "w")
            if f then f:write(txt); f:close() end
        end
    end)
end
local function log(msg)
    pcall(function()
        local ts = "?"
        pcall(function() ts = os.date("%H:%M:%S") end)
        table.insert(_SKIN_BUF, ts.." "..tostring(msg))
        if #_SKIN_BUF > 200 then table.remove(_SKIN_BUF, 1) end
        _skinFlush()
    end)
end
log("[SKIN] script loaded")

-- SW_Get / SW_Set Ã¢â‚¬â€ read/write LexusConfig toggles
local function SW_Get(key) return _G.LexusConfig and _G.LexusConfig[key] end
local function SW_Set(key, v)
    if _G.LexusConfig then _G.LexusConfig[key] = v end
    return true
end

-- One-shot bootstrap flag
local _bootstrapNotified = false

-- Optional timer helper stub (used in a few places as _G.SetTimer)
if not _G.SetTimer then
    _G.SetTimer = function(delay, fn) pcall(function() require("common.time_ticker").AddTimerOnce(delay, fn) end) end
end

-- ---- feature flags (all on) --------------------------------
if not _G.LexusConfig then
    _G.LexusConfig = {}
end
local cfg = _G.LexusConfig
cfg.ModSkin         = cfg.ModSkin         ~= false and true or false
cfg.KillCountUI     = cfg.KillCountUI     ~= false and true or false
cfg.SkinDeadBox     = cfg.SkinDeadBox     ~= false and true or false
cfg.KillMessage     = cfg.KillMessage     ~= false and true or false
cfg.SkinAttachment  = cfg.SkinAttachment  ~= false and true or false
cfg.ModEmote        = cfg.ModEmote        ~= false and true or false
local _slots = {
    "Suit","Top","Gloves","Bottom","Shoes","Bag","Helmet","Parachute",
    "M416","AKM","SCAR","M762","AUG","UMP","UZI","Groza","S12K","DBS",
    "Dacia","UAZ","Coupe","Buggy","Mirado",
}
for _, s in ipairs(_slots) do
    local k = "SkinEnable_"..s
    if cfg[k] == nil then cfg[k] = true end
end

-- ---- native settings menu (skin tab only) --------------------
-- Mirrors DUNG _G.InitModMenuTab but builds ONLY the Skins category.
-- If this tab appears in game Settings, the script is injected.
function _G.InitSkinMenuTab()
    if _G.SkinMenuInitialized then log("[SKIN] menu already init"); return end
    _G.SkinMenuInitialized = true
    log("[SKIN] InitSkinMenuTab start")

    local function T(vnText, enText)
        return _G.LexusLang == "EN" and (enText or vnText) or vnText
    end
    local function SW_Get(key)
        local v = _G.LexusConfig and _G.LexusConfig[key]
        if v == true or v == 1 then return 1 else return 2 end
    end
    local function SW_Set(key, v)
        if not _G.LexusConfig then return true end
        if v == 1 or v == true then _G.LexusConfig[key] = true
        else _G.LexusConfig[key] = false end
        return true
    end

    -- Text IDs for tab titles (own IDs Ã¢â‚¬â€ hacks page uses 999100)
    local FakeTextMap = {
        [999101] = T("SKIN MENU", "SKIN MENU"),
        [999005] = T("Skins", "Skins"),
    }
    pcall(function()
        local LocUtil = _G.LocUtil or package.loaded["client.common.LocUtil"]
        if not LocUtil then LocUtil = require("client.common.LocUtil") end
        if LocUtil and not LocUtil._IsSkinMenuHooked then
            for _, funcName in ipairs({"GetLocalizeResStr", "GetText", "GetTextByID", "GetLocalText", "GetLocalizeStr"}) do
                if LocUtil[funcName] then
                    local old_func = LocUtil[funcName]
                    LocUtil[funcName] = function(id)
                        if FakeTextMap[id] then return FakeTextMap[id] end
                        if type(id) == "string" and not tonumber(id) then return id end
                        if old_func then
                            local ok, res = pcall(old_func, id)
                            if ok then return res end
                        end
                        return ""
                    end
                end
            end
            LocUtil._IsSkinMenuHooked = true
            log("[SKIN] LocUtil hooked")
        end
    end)

    -- Build + register settings page
    pcall(function()
        local SettingPageDefine = require("client.logic.NewSetting.SettingPageDefine")
        local SettingCatalog = require("client.logic.NewSetting.SettingCatalog")
        local AliasMap = require("client.slua.umg.NewSetting.Item.AliasMap")
        if not (SettingPageDefine and SettingCatalog and AliasMap) then
            log("[SKIN] menu: Setting modules missing"); return
        end

        local StackSkin = {
            { Key = "ModMenu_ModEmote", UI = AliasMap.Switcher, Text = T("Unlock Emotes", "Unlock Emotes"), GetFunc = function() return SW_Get("ModEmote") end, SetFunc = function(c,v) return SW_Set("ModEmote", v) end },
            { Key = "ModMenu_ModSkin", UI = AliasMap.Switcher, Text = T("Mod Skin", "Mod Skin"), GetFunc = function() return SW_Get("ModSkin") end, SetFunc = function(c,v) return SW_Set("ModSkin", v) end },
            { Key = "ModMenu_SkinDeadBox", UI = AliasMap.Switcher, Text = T("Deadbox Skin", "Deadbox Skin"), GetFunc = function() return SW_Get("SkinDeadBox") end, SetFunc = function(c,v) return SW_Set("SkinDeadBox", v) end },
            { Key = "ModMenu_SkinAttachment", UI = AliasMap.Switcher, Text = T("Attachment Skin", "Attachment Skin"), GetFunc = function() return SW_Get("SkinAttachment") end, SetFunc = function(c,v) return SW_Set("SkinAttachment", v) end },
            { Key = "ModMenu_KillMessage", UI = AliasMap.Switcher, Text = T("Kill Message", "Kill Message"), GetFunc = function() return SW_Get("KillMessage") end, SetFunc = function(c,v) return SW_Set("KillMessage", v) end },
            { Key = "ModMenu_KillCountUI", UI = AliasMap.Switcher, Text = T("Kill Counter", "Kill Counter"), GetFunc = function() return SW_Get("KillCountUI") end, SetFunc = function(c,v) return SW_Set("KillCountUI", v) end },
        }

        if not SettingPageDefine.SkinMenu then
            SettingPageDefine.SkinMenu = {
                Key = "SkinMenu",
                Text = 999101,
                UIKey = "Setting_Page_Privacy",
                Category = { { Key = "Cat_Skin", Text = 999005, Stack = StackSkin } },
            }
            log("[SKIN] SkinMenu page created")
        end

        -- Skin page goes at the END (hacks page sits at top)
        local hasSkinMenu = false
        for _, page in ipairs(SettingCatalog) do
            if type(page) == "table" and page.Key == "SkinMenu" then hasSkinMenu = true; break end
        end
        if not hasSkinMenu then
            table.insert(SettingCatalog, SettingPageDefine.SkinMenu)
            log("[SKIN] SkinMenu appended to SettingCatalog")
        end
    end)

    -- Keep page injected when settings UI opens
    pcall(function()
        local UIManager = _G.UIManager
        if UIManager and not UIManager._IsSkinMenuHooked then
            local old_ShowUI = UIManager.ShowUI
            UIManager.ShowUI = function(config, ...)
                local args = {...}
                local n = select('#', ...)
                pcall(function()
                    if config and config.keyName then
                        local lowerKeyName = string.lower(config.keyName)
                        if string.find(lowerKeyName, "setting_main") and not string.find(lowerKeyName, "custom") then
                            local catalog = args[1]
                            if type(catalog) == "table" and catalog[1] and type(catalog[1]) == "table" and catalog[1].Key then
                                local hasSkinMenu = false
                                for _, page in ipairs(catalog) do
                                    if type(page) == "table" and page.Key == "SkinMenu" then hasSkinMenu = true; break end
                                end
                                if not hasSkinMenu then
                                    local SPD = require("client.logic.NewSetting.SettingPageDefine")
                                    if SPD and SPD.SkinMenu then table.insert(catalog, SPD.SkinMenu) end
                                end
                            end
                        end
                    end
                end)
                local table_unpack = table.unpack or unpack
                return old_ShowUI(config, table_unpack(args, 1, n))
            end
            UIManager._IsSkinMenuHooked = true
            log("[SKIN] UIManager.ShowUI hooked")
        end
    end)

    log("[SKIN] InitSkinMenuTab done")
end

