                local synDataRef = slua.IndexReference(currweapon.synData:Get(7), "defineID")
                local SkinID = synDataRef and slua.isValid(synDataRef) and synDataRef.TypeSpecificID or 0
                self.KillCounterItem:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.getKills(DefineID), SkinID)
            end
        end

        MyKillCountSubSystem.__inner_impl.CheckSupportKCUI = function(self) return _G.LexusConfig.KillCountUI end

        local o_UpdateMainKillCounterUI = MyKillCountSubSystem.__inner_impl.UpdateMainKillCounterUI
        MyKillCountSubSystem.__inner_impl.UpdateMainKillCounterUI = function(self, bShow, WeaponID, AvatarID)
            -- [ULTIMATE OPT] Immediately choke Game's UI call if off, PREVENT FLASH
            if not _G.LexusConfig.KillCountUI then
                o_UpdateMainKillCounterUI(self, false, WeaponID, AvatarID) -- Force parameter False
                local MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
                return
            end

            o_UpdateMainKillCounterUI(self, bShow, WeaponID, AvatarID)
            local MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
            local uCharacter = slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
            local currweapon = uCharacter:GetCurrentWeapon()
         
            if not bShow and MainKillCounter then
                UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter)
            elseif bShow and currweapon ~= nil then
                local DefineID = currweapon:GetItemDefineID().TypeSpecificID
                local currentEquipAvatrid = slua.IndexReference(currweapon.synData:Get(7), "defineID").TypeSpecificID
                local LogicKillCounter = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicKillCounter)
                local SupportKillCounter = LogicKillCounter:GetBaseKillCounterIdByWeaponId(DefineID)
                
                local curEquipedKillCounter = LogicKillCounter:GetEquipedKillCounterId(6114302174, currentEquipAvatrid)
                
                -- [FPS OPT] IDENTIFY MOD WEAPONS: Normal weapon ID < 1,000,000, Mod weapon ID > 1,000,000
                local isModdedSkin = (currentEquipAvatrid and currentEquipAvatrid > 1000000)
                
                -- Close UI if pistol, knife, PAN or NORMAL WEAPON WITHOUT SKIN
                if (SupportKillCounter == nil or not isModdedSkin) then
                    if MainKillCounter then
                        UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter)
                    end
                else
                    -- Show UI if Mod weapon (Even if curEquipedKillCounter returns nil due to server not recognizing)
                    if not MainKillCounter then
                        UIManager.ShowUI(UIManager.UI_Config_InGame.MainKillCounter, DefineID, currentEquipAvatrid)
                        MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                        if MainKillCounter then
                            MainKillCounter:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.getKills(DefineID), currentEquipAvatrid)
                        end
                    else
                        MainKillCounter:UpdateWeaponID(DefineID, currentEquipAvatrid)
                        MainKillCounter:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.getKills(DefineID), currentEquipAvatrid)
                    end
                end
            end
        end

        local o_CheckNeedMainKillCounterUI = MyKillCountSubSystem.__inner_impl.CheckNeedMainKillCounterUI
        MyKillCountSubSystem.__inner_impl.CheckNeedMainKillCounterUI = function(self, Weapon, PlayerID)
            if not _G.LexusConfig.KillCountUI then return end -- BLOCK WHEN OFF
            local uCharacter = slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
            local currweapon = uCharacter:GetCurrentWeapon()
            if currweapon ~= nil then
                local defineID = currweapon:GetItemDefineID()
                local DefineID = defineID and slua.isValid(defineID) and defineID.TypeSpecificID or 0
                local synDataRef = slua.IndexReference(currweapon.synData:Get(7), "defineID")
                local SkinID = synDataRef and slua.isValid(synDataRef) and synDataRef.TypeSpecificID or 0
                self:UpdateMainKillCounterUI(true, DefineID, SkinID)
            end
        end
    end
end)

-- Updater Loop (Cache Optimized: Only Update UI on weapon change or Kill network)
local _lastKCWeaponID = 0
local _lastKCSkinID = 0

_G.GameAvatarHandlerkillcounter = function()
    local UIManager = require("client.slua_ui_framework.manager")
    
    if not _G.LexusConfig.KillCountUI then
        local MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
        if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
        return 
    end

    local PlayerController = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if not PlayerController or not slua.isValid(PlayerController) then return end
    
    local uCharacter = PlayerController:GetPlayerCharacterSafety()
    if not uCharacter or not slua.isValid(uCharacter) then return end
    
    local currweapon = uCharacter:GetCurrentWeapon()
    if currweapon and slua.isValid(currweapon) then
        -- Safely get DefineID, no RAM garbage
        local defineIDObj = currweapon:GetItemDefineID()
        local currentWeaponID = (defineIDObj and slua.isValid(defineIDObj)) and defineIDObj.TypeSpecificID or 0
        
        -- Get Skin ID from Skin V7.5 system Cache (Ultra light, no SLUA calls)
        local currentSkinID = 0
        if _G.AddOutfitLastAppliedSkin and _G.AddOutfitLastAppliedSkin[currentWeaponID] then
            currentSkinID = _G.AddOutfitLastAppliedSkin[currentWeaponID]
        end

        -- ULTRA OPT: Only send UI update command if WEAPON JUST CHANGED or JUST KILLED
        if _G.UpdateMyKillCounter or currentWeaponID ~= _lastKCWeaponID or currentSkinID ~= _lastKCSkinID then
            _lastKCWeaponID = currentWeaponID
            _lastKCSkinID = currentSkinID
            _G.UpdateMyKillCounter = false
            
            if _G.OurkillCountSystem then
                _G.OurkillCountSystem:UpdateMainKillCounterUI(true, currentWeaponID, currentSkinID)
            end
        end
    else
        _lastKCWeaponID = 0
        _lastKCSkinID = 0
        local MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
        if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
    end
end

local function LobbyTickSetup()
    if not _G.CounterUpdated then
        _G.CounterUpdated = true
        _G.loadKillCountFromFile()
    end
    -- REMOVED translateec.conf FILE SCAN LOGIC THAT CAUSED LAG
end

-- Activate Hooks and Loop
pcall(function()
    installTeamBroadcastHooks()
    LobbyTickSetup() -- Only call file read once on game entry, no repetition
    
    local ticker = require("common.time_ticker")
    if ticker and ticker.AddTimerLoop then
        ticker.AddTimerLoop(0, _G.GameAvatarHandlerkillcounter, -1, 0.5)
        -- REMOVED 0.4 SECOND FILE READ LOOP TO PREVENT FPS DROP
    end
end)
-- ==============================================================================

    F.startVehicleSkinTicker()
    F.startMatchDriver() -- persistent in-match re-apply (wardrobe-alone mode)
    if not _G.AddOutfitVehInitTimers then
        _G.AddOutfitVehInitTimers = true
        F.later(1.5, function() pcall(F.applyVehicleSkinsToPC) end)
        F.later(4.0, function() pcall(F.applyVehicleSkinsToPC) end)
    end

    pcall(function()
        if F.isInRealMatch() then
            local char = F.getLocalChar()
            if char then
                F.bootstrapMatch(char)
            end
        end
    end)

    local firstLobby = not _G.AddOutfitLobbyInitDone
    log("[SKIN] F.start: attempting injectAll firstLobby="..tostring(firstLobby))
    if F.injectAll() then
        if firstLobby then _G.AddOutfitLobbyInitDone = true end
        log("[SKIN] injectAll OK on first try")
        F.afterInjectApply(firstLobby)
        return
    end
    log("[SKIN] injectAll FAILED first try Ã¢â‚¬â€ scheduling retries (max "..INJECT_RETRY_MAX..")")
    local tries = 0
    local function retry()
        tries = tries + 1
        log("[SKIN] injectAll retry #"..tries)
        if F.injectAll() then
            local ft = not _G.AddOutfitLobbyInitDone
            if ft then _G.AddOutfitLobbyInitDone = true end
            log("[SKIN] injectAll OK on retry #"..tries)
            F.afterInjectApply(ft)
            return
        end
        log("[SKIN] injectAll still failed on retry #"..tries)
        if tries < INJECT_RETRY_MAX then F.later(INJECT_RETRY_SEC, retry)
        else log("[SKIN] injectAll GAVE UP after "..tries.." retries") end
    end
    F.later(INJECT_RETRY_SEC, retry)
end

_G.AddOutfit = F
F.start()

-- [FIX VIP] AUTO RESTORE SKIN IN LOBBY ON GAME STARTUP
_G.AddOutfitLobbyRestored = false

local function AutoRestoreLobbySkin()
    if _G.AddOutfitLobbyRestored then return end
    
    -- [FIX VIP] Block auto skin loading on game startup if toggle is off
    if not _G.LexusConfig.ModSkin then return end
    
    -- [LOBBY SLEEP FLAG]: If already on plane entering match -> Sleep, no longer reading Lobby file!
    if _G.AddOutfit and _G.AddOutfit.isInRealMatch() then return end
    
    pcall(function()
        -- Retry settings menu in case Setting modules loaded after boot
        if not _G.SkinMenuInitialized and _G.InitSkinMenuTab then
            _G.InitSkinMenuTab()
        end
        local inLobby = GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity()
        local hasUID  = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
        log("[SKIN] AutoRestore tick: inLobby="..tostring(inLobby).." hasUID="..tostring(hasUID ~= nil))
        if inLobby then
            -- Wait for DataMgr to finish loading character UID (Prevents early load glitch)
            if hasUID then
                local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
                log("[SKIN] AutoRestore: LMC="..tostring(LMC ~= nil).." GetCurPage="..tostring(LMC and LMC.GetCurPage ~= nil))
                if LMC and LMC.GetCurPage then
                    if _G.AddOutfit and _G.AddOutfit.reapplyLobbyEquipped then
                        -- Fire sequential commands: Read File -> Assign Data -> Draw on character
                        log("[SKIN] AutoRestore: firing persistLoadFromDisk")
                        _G.AddOutfit.persistLoadFromDisk() 
                        log("[SKIN] AutoRestore: firing persistApplyLoaded")
                        _G.AddOutfit.persistApplyLoaded() 
                        log("[SKIN] AutoRestore: firing reapplyLobbyEquipped")
                        _G.AddOutfit.reapplyLobbyEquipped() 
                        
                        -- Set completion flag
                        _G.AddOutfitLobbyRestored = true
                        log("[SKIN] AutoRestore: DONE")
                    end
                end
            end
        end
    end)
end

-- Background run 1 second/cycle on game entry, auto-stops when loaded
pcall(function()
    local ticker = require("common.time_ticker")
    if ticker and ticker.AddTimerLoop then
        ticker.AddTimerLoop(0, AutoRestoreLobbySkin, -1, 1.0)
    end
end)

-- [MANDATORY] IF YOU CLICK "YES" WHILE STANDING IN MATCH, ACTIVATE SKIN ON CHARACTER IMMEDIATELY
pcall(function()
    if _G.AddOutfit and _G.AddOutfit.isInRealMatch() then
        local char = _G.AddOutfit.getLocalChar()
        if char then _G.AddOutfit.bootstrapMatch(char) end
    else
        if _G.AddOutfit and _G.AddOutfit.reapplyLobbyEquipped then
            _G.AddOutfit.reapplyLobbyEquipped()
        end
    end
end)

end -- END LoadModSkinSystem FUNCTION

-- ---- boot-wait fire ----------------------------------------
-- WardRobeHandler chunk can run before game Lua modules (time_ticker,
-- settings, wardrobe) exist. Firing immediately = silent death inside
-- pcalls. So poll until time_ticker is requirable, then fire.
-- Uses timer_manager Delay (the same timer the injector itself uses,
-- so it is guaranteed to exist at chunk time).
local _bootTries = 0
local _bootDone = false
local function _bootReady()
    local ok, tt = pcall(require, "common.time_ticker")
    if ok and tt then return true end
    return false
end
local function _bootFire()
    if _bootDone then return end
    _bootDone = true
    log("[SKIN] boot ready after "..tostring(_bootTries).." tries Ã¢â‚¬â€ firing")
    pcall(function() if _G.InitSkinMenuTab then _G.InitSkinMenuTab() end end)
    pcall(function() if _G.LoadModSkinSystem then _G.LoadModSkinSystem() end end)
    -- Visible proof of injection, once per session
    pcall(function()
        if not _G._SkinPopupShown then
            _G._SkinPopupShown = true
            local Msg = (package.loaded and package.loaded["client.slua.logic.common.logic_common_msg_box"])
                     or require("client.slua.logic.common.logic_common_msg_box")
            if Msg and Msg.Show then
                Msg.Show(1, "SKIN", "Skin system injected", function() end, function() end)
                log("[SKIN] popup shown")
            else
                log("[SKIN] popup: Msg module missing")
            end
        end
    end)
end
local function _bootTick()
    if _bootDone then return end
    _bootTries = _bootTries + 1
    if _bootReady() then _bootFire(); return end
    if _bootTries == 1 or _bootTries % 10 == 0 then
        log("[SKIN] boot wait try "..tostring(_bootTries))
    end
    if _bootTries < 120 then
        local scheduled = false
        pcall(function()
            local MM = ModuleManager
            local tm = MM and MM.GetModule and MM.GetModule(MM.CommonModuleConfig and MM.CommonModuleConfig.timer_manager)
            if tm and tm.Delay then tm:Delay(1000, _bootTick); scheduled = true end
        end)
        if not scheduled then
            log("[SKIN] boot: no timer_manager, retrying via time_ticker")
            pcall(function() require("common.time_ticker").AddTimerOnce(1.0, _bootTick) end)
        end
    else
        log("[SKIN] boot wait GAVE UP Ã¢â‚¬â€ firing anyway")
        _bootFire()
    end
end
if _bootReady() then _bootFire() else _bootTick() end

-- ---- injector bridge ---------------------------------------
-- WardRobeHandler.lua calls _G._RestoreWornFakeItems() right after
-- pcall(chunk) + once more after 1s. Expose it so the injector's own
-- restore timing drives our reapply instead of being a no-op.
_G._RestoreWornFakeItems = function()
    log("[SKIN] _RestoreWornFakeItems called by injector")
    pcall(function()
        if _G.AddOutfit and _G.AddOutfit.reapplyLobbyEquipped then
            _G.AddOutfit.persistLoadFromDisk()
            _G.AddOutfit.persistApplyLoaded()
            _G.AddOutfit.reapplyLobbyEquipped()
            _G.AddOutfitLobbyRestored = true
        else
            log("[SKIN] _RestoreWornFakeItems: AddOutfit not ready")
        end
    end)
end